   569  // Converts all materials in the given array and stores them in the scene's material list.
   570  void XFileImporter::ConvertMaterials( aiScene* pScene, std::vector<XFile::Material>& pMaterials)
   571  {
   572      // count the non-referrer materials in the array
   573      unsigned int numNewMaterials( 0 );
   574      for ( unsigned int a = 0; a < pMaterials.size(); ++a ) {
   575          if ( !pMaterials[ a ].mIsReference ) {
   576              ++numNewMaterials;
   577          }
   578      }
   579
   580      // resize the scene's material list to offer enough space for the new materials
   581      if( numNewMaterials > 0 ) {
   582          aiMaterial** prevMats = pScene->mMaterials;
   583          pScene->mMaterials = new aiMaterial*[pScene->mNumMaterials + numNewMaterials];
   584          if( nullptr != prevMats)  {
   585              ::memcpy( pScene->mMaterials, prevMats, pScene->mNumMaterials * sizeof( aiMaterial*));
   586              delete [] prevMats;
   587          }
   588      }
   589
   590      // convert all the materials given in the array
   591      for( unsigned int a = 0; a < pMaterials.size(); ++a ) {
   592          XFile::Material& oldMat = pMaterials[a];
   593          if( oldMat.mIsReference) {
   594              // find the material it refers to by name, and store its index
   595              for( size_t b = 0; b < pScene->mNumMaterials; ++b ) {
   596                  aiString name;
   597                  pScene->mMaterials[b]->Get( AI_MATKEY_NAME, name);
   598                  if( strcmp( name.C_Str(), oldMat.mName.data()) == 0 ) {
   599                      oldMat.sceneIndex = a;
   600                      break;
   601                  }
   602              }
   603
   604              if( oldMat.sceneIndex == SIZE_MAX ) {
   605                  ASSIMP_LOG_WARN_F( "Could not resolve global material reference \"", oldMat.mName, "\"" );
   606                  oldMat.sceneIndex = 0;
   607              }
   608
