   484  // ------------------------------------------------------------------------------------------------
   485  void XFileParser::ParseDataObjectSkinWeights(Mesh *pMesh) {
   486      if (nullptr == pMesh) {
   487          return;
   488      }
   489      readHeadOfDataObject();
   490
